import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"开发者 API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/developer-api.md","filePath":"guide/developer-api.md","lastUpdated":1788621106000}`),a={name:`guide/developer-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="开发者-api" tabindex="-1">开发者 API <a class="header-anchor" href="#开发者-api" aria-label="Permalink to “开发者 API”">​</a></h1><h2 id="创建密钥" tabindex="-1">创建密钥 <a class="header-anchor" href="#创建密钥" aria-label="Permalink to “创建密钥”">​</a></h2><p>在开发者页面创建个人 API 密钥，并只授予业务需要的作用域。完整密钥只在创建时显示一次；丢失后应撤销旧密钥并重新创建。</p><p>请求地址、鉴权格式和当前接口定义以开发者页面提供的 OpenAPI 说明为准。示例：</p><div class="language-http"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;API_KEY&gt;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span></code></pre></div><p>不要把真实密钥写进前端代码、公开仓库、日志或工单。服务端应用应通过环境变量或密钥管理服务注入。</p><h2 id="作用域" tabindex="-1">作用域 <a class="header-anchor" href="#作用域" aria-label="Permalink to “作用域”">​</a></h2><p>作用域用于限制密钥能够读取或修改的资源。优先创建只读密钥；确需写操作时，再单独创建用途明确、有效期受控的密钥。业务停用或人员变更后立即撤销。</p><h2 id="响应与错误" tabindex="-1">响应与错误 <a class="header-anchor" href="#响应与错误" aria-label="Permalink to “响应与错误”">​</a></h2><p>API 使用 HTTP 状态码表达结果：<code>2xx</code> 表示成功，<code>400</code> 表示参数问题，<code>401</code> 表示凭据无效，<code>403</code> 表示权限不足，<code>404</code> 表示资源不存在，<code>429</code> 表示请求过快，<code>5xx</code> 表示服务端异常。</p><p>客户端应设置连接和读取超时；对网络错误及部分 <code>5xx</code> 使用带随机抖动的指数退避。创建订单、发送邮件等有副作用的请求不要盲目重试，应先查询结果或使用接口提供的幂等机制。</p><h2 id="密钥轮换" tabindex="-1">密钥轮换 <a class="header-anchor" href="#密钥轮换" aria-label="Permalink to “密钥轮换”">​</a></h2><ol><li>创建新密钥并赋予相同或更小的作用域。</li><li>更新应用配置并验证请求成功。</li><li>撤销旧密钥。</li><li>检查审计记录，确认没有旧密钥流量。</li></ol>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};